selector_to_html = {"a[href=\"#module-contents\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Module Contents<a class=\"headerlink\" href=\"#module-contents\" title=\"Link to this heading\">\u00b6</a></h2>", "a[href=\"#pyskyfire.pump.disk_friction.disk_friction_power\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.pump.disk_friction.disk_friction_power\">\n<span class=\"sig-prename descclassname\"><span class=\"pre\">pyskyfire.pump.disk_friction.</span></span><span class=\"sig-name descname\"><span class=\"pre\">disk_friction_power</span></span><span class=\"sig-paren\">(</span><em class=\"sig-param\"><span class=\"keyword-only-separator o\"><abbr title=\"Keyword-only parameters separator (PEP 3102)\"><span class=\"pre\">*</span></abbr></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">rho</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">mu</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">n</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">radius</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">axial_gap</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">inner_radius</span></span><span class=\"o\"><span class=\"pre\">=</span></span><span class=\"default_value\"><span class=\"pre\">0.0</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">roughness</span></span><span class=\"o\"><span class=\"pre\">=</span></span><span class=\"default_value\"><span class=\"pre\">0.0</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">cone_angle_deg</span></span><span class=\"o\"><span class=\"pre\">=</span></span><span class=\"default_value\"><span class=\"pre\">0.0</span></span></em><span class=\"sig-paren\">)</span></dt><dd><p>Friction power on one face of a rotating disk [W], G\u00fclich (T3.6.2).</p></dd>", "a[href=\"DiskFriction.html#pyskyfire.pump.disk_friction.DiskFriction\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.pump.disk_friction.DiskFriction\">\n<span class=\"property\"><span class=\"k\"><span class=\"pre\">class</span></span><span class=\"w\"> </span></span><span class=\"sig-prename descclassname\"><span class=\"pre\">pyskyfire.pump.disk_friction.</span></span><span class=\"sig-name descname\"><span class=\"pre\">DiskFriction</span></span></dt><dd><p>The disk friction of one impeller, all its wetted faces together.</p><p><code class=\"docutils literal notranslate\"><span class=\"pre\">inner_radii</span></code> holds one entry per face: a shrouded impeller has two, the\nfront shroud starting at its eye seal and the back at the hub. An open\nimpeller has only the back one.</p></dd>", "a[href=\"#module-pyskyfire.pump.disk_friction\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">pyskyfire.pump.disk_friction<a class=\"headerlink\" href=\"#module-pyskyfire.pump.disk_friction\" title=\"Link to this heading\">\u00b6</a></h1><p>Friction on the outside of a spinning impeller: its disk friction loss.</p><p>A shrouded impeller\u2019s two outer faces turn in the fluid filling the gaps\nbetween them and the casing. The shear on them costs shaft power and heats the\nfluid. The flow through the blades never sees any of it, so it is charged here,\nnot in the hydraulic efficiency.</p>", "a[href=\"#references\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">References<a class=\"headerlink\" href=\"#references\" title=\"Link to this heading\">\u00b6</a></h2><p>G\u00fclich, J. F., <em>Centrifugal Pumps</em>, 4th ed., Springer, 2020. Table 3.6.</p>", "a[href=\"#functions\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Functions<a class=\"headerlink\" href=\"#functions\" title=\"Link to this heading\">\u00b6</a></h2>", "a[href=\"#classes\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Classes<a class=\"headerlink\" href=\"#classes\" title=\"Link to this heading\">\u00b6</a></h2>"}
skip_classes = ["headerlink", "sd-stretched-link"]

window.onload = function () {
    for (const [select, tip_html] of Object.entries(selector_to_html)) {
        const links = document.querySelectorAll(` ${select}`);
        for (const link of links) {
            if (skip_classes.some(c => link.classList.contains(c))) {
                continue;
            }

            tippy(link, {
                content: tip_html,
                allowHTML: true,
                arrow: true,
                placement: 'auto-start', maxWidth: 600, interactive: false,
                onShow(instance) {MathJax.typesetPromise([instance.popper]).then(() => {});},
            });
        };
    };
    console.log("tippy tips loaded!");
};
